// PLAN:
// 1. Setup & Theme: Inject NU brand CSS variables (Pantone 200 Red, stark white, specific fonts). Strict adherence to color/spacing tokens.
// 2. Seed Data: Define MarketEvents and Clients based on the spec.
// 3. State Machine: App component manages `currentScreen` (dashboard -> client_triage -> email_editor -> compliance_review).
// 4. AI Integration:
//    - `fetchPrioritizedClients`: Calls Anthropic to rank clients based on market event.
//    - `fetchDraft`: Calls Anthropic to generate an email with <fact> tags.
//    - `fetchInlineEdit`: Calls Gemini to revise a specific paragraph.
// 5. Components:
//    - `Header`: NU branded top bar.
//    - `DemoControls`: For reviewer navigation.
//    - `Dashboard`: Shows market alert, triggers prioritization.
//    - `ClientTriage`: Shows ranked list with staggered animation.
//    - `EmailEditor`: Complex view. Parses <fact> tags into interactive elements. Handles paragraph selection for inline editing.
//    - `InlineEditor`: Floating menu for Gemini prompt, shows simulated diff.
//    - `ComplianceReview`: Simulated scanning animation, success state.
// 6. Micro-interactions: Hover states on facts, button states, staggered list entrances.

const SEED_MARKET_EVENTS = [
  {
    id: "EVT-001",
    title: "Q3 Tech Sector Dip",
    description: "NASDAQ drops 8% over 48 hours due to supply chain fears.",
    severity: "High"
  }
];

const SEED_CLIENTS = [
  {
    id: "CLI-101",
    name: "Marcus & Sarah Vance",
    aum: "$5,200,000",
    risk_tolerance: "Moderate-Conservative",
    tech_exposure_percent: "18%",
    recent_crm_note: "Just returned from anniversary trip to Italy; daughter Chloe starting at NYU in the fall."
  },
  {
    id: "CLI-102",
    name: "David Chen",
    aum: "$1,800,000",
    risk_tolerance: "Aggressive",
    tech_exposure_percent: "45%",
    recent_crm_note: "Looking to buy a second home in Tahoe next year."
  },
  {
    id: "CLI-103",
    name: "Elena Rodriguez",
    aum: "$3,100,000",
    risk_tolerance: "Conservative",
    tech_exposure_percent: "5%",
    recent_crm_note: "Concerned about inflation impacting fixed income yields."
  }
];

// --- AI Helpers ---

async function fetchPrioritizedClients(event, clients) {
  try {
    const prompt = `
      You are a wealth management assistant. 
      Market Event: ${event.title} - ${event.description}
      Client Data: ${JSON.stringify(clients)}

      Identify the top clients who need immediate contact based on their portfolio exposure and risk tolerance relative to this event.
      Return ONLY a valid JSON array of objects with 'client_id' and a 1-sentence 'rationale'.
      Example: [{"client_id": "CLI-101", "rationale": "High tech exposure combined with conservative risk tolerance requires immediate reassurance."}]
    `;

    const res = await fetch('/api/ai/anthropic', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: "claude-opus-4-6",
        max_tokens: 1000,
        messages: [{ role: "user", content: prompt }]
      })
    });
    const data = await res.json();
    let text = data?.content?.[0]?.text || "[]";
    // Clean markdown if present
    text = text.replace(/```json/g, '').replace(/```/g, '').trim();
    return JSON.parse(text);
  } catch (e) {
    console.error("AI Prioritization Error:", e);
    // Fallback for demo resilience
    return [
      { client_id: "CLI-101", rationale: "High tech exposure (18%) conflicts with Moderate-Conservative profile during this dip." },
      { client_id: "CLI-102", rationale: "Massive tech exposure (45%) requires a check-in despite aggressive profile." }
    ];
  }
}

async function fetchDraft(client, event) {
  try {
    const prompt = `
      You are an expert financial advisor drafting an email to a high-net-worth client. 
      Tone must be reassuring, professional, and highly personalized. Do not make promises about future returns.

      Client: ${client.name}
      Context: ${event.title} - ${event.description}
      CRM Notes: ${client.recent_crm_note}
      Portfolio: AUM ${client.aum}, Tech Exposure ${client.tech_exposure_percent}, Risk: ${client.risk_tolerance}

      CRITICAL INSTRUCTION: Wrap specific facts pulled from the CRM or portfolio in <fact source="Source Name">fact text</fact> tags.
      Example: I hope you enjoyed your <fact source="CRM Note">trip to Italy</fact>. I noticed your <fact source="Portfolio Data">18% tech exposure</fact>...

      Write 3 short paragraphs. Do not include a subject line, just the body.
    `;

    const res = await fetch('/api/ai/anthropic', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: "claude-opus-4-6",
        max_tokens: 1500,
        messages: [{ role: "user", content: prompt }]
      })
    });
    const data = await res.json();
    return data?.content?.[0]?.text || "Error generating draft.";
  } catch (e) {
    console.error("AI Draft Error:", e);
    return `Hi ${client.name},\n\nI hope you are recovering well from your <fact source="CRM Note">trip to Italy</fact>! I'm reaching out today because of the recent <fact source="Market Alert">Tech Sector Dip</fact>.\n\nGiven your <fact source="Portfolio Data">${client.tech_exposure_percent} tech exposure</fact> and your focus on preparing for <fact source="CRM Note">Chloe starting at NYU</fact>, I wanted to review our strategy. Your portfolio is built to withstand these short-term fluctuations.\n\nLet's schedule a brief call next week to discuss.`;
  }
}

async function fetchInlineEdit(originalText, instruction, context) {
  try {
    const prompt = `
      You are an AI copyeditor for a wealth advisor.
      Original text: "${originalText}"
      Instruction: "${instruction}"
      Surrounding context: "${context}"

      Revise the original text based strictly on the instruction. Maintain a professional, reassuring tone.
      Return ONLY the revised text, nothing else. Keep any <fact> tags intact if they are still relevant.
    `;

    const res = await fetch('/api/ai/gemini-compat', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-openai-endpoint': 'chat' },
      body: JSON.stringify({
        model: 'gemini-3.1-pro-preview',
        messages: [{ role: 'user', content: prompt }],
        temperature: 0.3,
        max_tokens: 800,
      })
    });
    const data = await res.json();
    return data?.choices?.[0]?.message?.content?.trim() || originalText;
  } catch (e) {
    console.error("AI Edit Error:", e);
    return "This is a simulated revised paragraph focusing on long-term stability rather than short-term alarm.";
  }
}

// --- Utility Components ---

const Button = ({ children, variant = 'primary', onClick, disabled, className = '', icon: Icon }) => {
  const baseStyle = "inline-flex items-center justify-center px-4 font-body font-semibold transition-all duration-200 ease-standard disabled:opacity-50 disabled:cursor-not-allowed";
  const heightStyle = "h-[48px]";
  const radiusStyle = "rounded-[2px]";

  const variants = {
    primary: "bg-nu-red text-white hover:bg-friction hover:-translate-y-[1px] hover:shadow-md active:translate-y-0 active:shadow-none",
    secondary: "bg-surface text-text-primary border border-border hover:bg-[rgba(0,0,0,0.05)]",
    ghost: "bg-transparent text-text-secondary hover:bg-surface hover:text-text-primary"
  };

  return (
    <button 
      onClick={onClick} 
      disabled={disabled}
      className={`${baseStyle} ${heightStyle} ${radiusStyle} ${variants[variant]} ${className}`}
    >
      {Icon && <Icon size={18} className="mr-2" />}
      {children}
    </button>
  );
};

const Card = ({ children, className = '' }) => (
  <div className={`bg-white border border-border rounded-[4px] shadow-sm ${className}`}>
    {children}
  </div>
);

const Badge = ({ children, variant = 'neutral', className = '' }) => {
  const variants = {
    neutral: "bg-surface text-text-secondary border-border",
    warning: "bg-[rgba(181,101,29,0.1)] text-warning border-[rgba(181,101,29,0.2)]",
    success: "bg-[rgba(15,138,75,0.1)] text-success border-[rgba(15,138,75,0.2)]",
    ai: "bg-[rgba(200,16,46,0.1)] text-nu-red border-[rgba(200,16,46,0.2)]"
  };
  return (
    <span className={`inline-flex items-center px-2 py-1 rounded-[2px] text-xs font-label border ${variants[variant]} ${className}`}>
      {children}
    </span>
  );
};

// Parses text containing <fact source="...">...</fact> into React nodes
const RichTextWithFacts = ({ text }) => {
  if (!text) return null;

  const parts = text.split(/(<fact source="[^"]+">.*?<\/fact>)/g);

  return (
    <span className="font-body text-text-primary leading-relaxed">
      {parts.map((part, i) => {
        const match = part.match(/<fact source="([^"]+)">(.*?)<\/fact>/);
        if (match) {
          const source = match[1];
          const content = match[2];
          return (
            <span key={i} className="relative group inline-block cursor-help">
              <span className="border-b border-dashed border-nu-red text-text-primary group-hover:bg-[rgba(200,16,46,0.1)] group-hover:border-solid transition-colors duration-200">
                {content}
              </span>
              <span className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 px-2 py-1 bg-text-primary text-white text-xs rounded-[2px] opacity-0 group-hover:opacity-100 transition-opacity duration-200 whitespace-nowrap pointer-events-none z-10 font-label">
                Source: {source}
              </span>
            </span>
          );
        }
        return <span key={i}>{part}</span>;
      })}
    </span>
  );
};

// --- Screen Components ---

