// --- AI Helpers ---

async function fetchPrioritizedClients(event, clients) {
  try {
    const prompt = `
      You are a wealth management assistant. 
      Market Event: ${event.title} - ${event.description}
      Client Data: ${JSON.stringify(clients)}

      Identify the top clients who need immediate contact based on their portfolio exposure and risk tolerance relative to this event.
      Return ONLY a valid JSON array of objects with 'client_id' and a 1-sentence 'rationale'.
      Example: [{"client_id": "CLI-101", "rationale": "High tech exposure combined with conservative risk tolerance requires immediate reassurance."}]
    `;

    const res = await fetch('/api/ai/anthropic', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: "claude-opus-4-6",
        max_tokens: 1000,
        messages: [{ role: "user", content: prompt }]
      })
    });
    const data = await res.json();
    let text = data?.content?.[0]?.text || "[]";
    // Clean markdown if present
    text = text.replace(/```json/g, '').replace(/```/g, '').trim();
    return JSON.parse(text);
  } catch (e) {
    console.error("AI Prioritization Error:", e);
    // Fallback for demo resilience
    return [
      { client_id: "CLI-101", rationale: "High tech exposure (18%) conflicts with Moderate-Conservative profile during this dip." },
      { client_id: "CLI-102", rationale: "Massive tech exposure (45%) requires a check-in despite aggressive profile." }
    ];
  }
}

async function fetchDraft(client, event) {
  try {
    const prompt = `
      You are an expert financial advisor drafting an email to a high-net-worth client. 
      Tone must be reassuring, professional, and highly personalized. Do not make promises about future returns.

      Client: ${client.name}
      Context: ${event.title} - ${event.description}
      CRM Notes: ${client.recent_crm_note}
      Portfolio: AUM ${client.aum}, Tech Exposure ${client.tech_exposure_percent}, Risk: ${client.risk_tolerance}

      CRITICAL INSTRUCTION: Wrap specific facts pulled from the CRM or portfolio in <fact source="Source Name">fact text</fact> tags.
      Example: I hope you enjoyed your <fact source="CRM Note">trip to Italy</fact>. I noticed your <fact source="Portfolio Data">18% tech exposure</fact>...

      Write 3 short paragraphs. Do not include a subject line, just the body.
    `;

    const res = await fetch('/api/ai/anthropic', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: "claude-opus-4-6",
        max_tokens: 1500,
        messages: [{ role: "user", content: prompt }]
      })
    });
    const data = await res.json();
    return data?.content?.[0]?.text || "Error generating draft.";
  } catch (e) {
    console.error("AI Draft Error:", e);
    return `Hi ${client.name},\n\nI hope you are recovering well from your <fact source="CRM Note">trip to Italy</fact>! I'm reaching out today because of the recent <fact source="Market Alert">Tech Sector Dip</fact>.\n\nGiven your <fact source="Portfolio Data">${client.tech_exposure_percent} tech exposure</fact> and your focus on preparing for <fact source="CRM Note">Chloe starting at NYU</fact>, I wanted to review our strategy. Your portfolio is built to withstand these short-term fluctuations.\n\nLet's schedule a brief call next week to discuss.`;
  }
}

async function fetchInlineEdit(originalText, instruction, context) {
  try {
    const prompt = `
      You are an AI copyeditor for a wealth advisor.
      Original text: "${originalText}"
      Instruction: "${instruction}"
      Surrounding context: "${context}"

      Revise the original text based strictly on the instruction. Maintain a professional, reassuring tone.
      Return ONLY the revised text, nothing else. Keep any <fact> tags intact if they are still relevant.
    `;

    const res = await fetch('/api/ai/gemini-compat', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-openai-endpoint': 'chat' },
      body: JSON.stringify({
        model: 'gemini-3.1-pro-preview',
        messages: [{ role: 'user', content: prompt }],
        temperature: 0.3,
        max_tokens: 800,
      })
    });
    const data = await res.json();
    return data?.choices?.[0]?.message?.content?.trim() || originalText;
  } catch (e) {
    console.error("AI Edit Error:", e);
    return "This is a simulated revised paragraph focusing on long-term stability rather than short-term alarm.";
  }
}

