// Parses text containing <fact source="...">...</fact> into React nodes
const RichTextWithFacts = ({ text }) => {
  if (!text) return null;

  const parts = text.split(/(<fact source="[^"]+">.*?<\/fact>)/g);

  return (
    <span className="font-body text-text-primary leading-relaxed">
      {parts.map((part, i) => {
        const match = part.match(/<fact source="([^"]+)">(.*?)<\/fact>/);
        if (match) {
