  const [inlinePrompt, setInlinePrompt] = React.useState("");
  const [isEditing, setIsEditing] = React.useState(false);
  const [diffResult, setDiffResult] = React.useState(null); // { oldText, newText }

  React.useEffect(() => {
    if (draftContent) {
      // Split by double newline to get paragraphs
      setParagraphs(draftContent.split('\n\n').filter(p => p.trim() !== ''));
    }
  }, [draftContent]);

  const handleInlineEditSubmit = async () => {
    if (!inlinePrompt.trim() || selectedIdx === null) return;
    setIsEditing(true);

    const originalText = paragraphs[selectedIdx];
    const context = paragraphs.join('\n\n');

    const newText = await fetchInlineEdit(originalText, inlinePrompt, context);

    setDiffResult({ oldText: originalText, newText });
    setIsEditing(false);
  };

  const acceptDiff = () => {
    const newParagraphs = [...paragraphs];
    newParagraphs[selectedIdx] = diffResult.newText;
    setParagraphs(newParagraphs);
    setDiffResult(null);
    setSelectedIdx(null);
    setInlinePrompt("");
  };

  const rejectDiff = () => {
    setDiffResult(null);
    setInlinePrompt("");
  };

  return (
    <motion.div 
      initial={{ opacity: 0 }} 
      animate={{ opacity: 1 }} 
      exit={{ opacity: 0 }}
      className="max-w-6xl mx-auto p-8 grid grid-cols-12 gap-8"
    >
      {/* Sidebar Context */}
      <div className="col-span-3 space-y-6">
        <button className="text-text-secondary hover:text-text-primary flex items-center text-sm font-label transition-colors">
          <lucide.ArrowLeft size={16} className="mr-2" /> Back to Triage
        </button>

        <Card className="p-6 bg-surface">
          <h3 className="font-display text-lg font-bold mb-4 border-b border-border pb-2">Client Context</h3>
          <div className="space-y-4 font-body text-sm">
            <div>
              <div className="text-text-secondary opacity-70 mb-1">Name</div>
              <div className="font-bold">{client.name}</div>
            </div>
            <div>
              <div className="text-text-secondary opacity-70 mb-1">AUM</div>
              <div className="font-data">{client.aum}</div>
            </div>
            <div>
              <div className="text-text-secondary opacity-70 mb-1">Risk Profile</div>
              <div>{client.risk_tolerance}</div>
            </div>
            <div>
              <div className="text-text-secondary opacity-70 mb-1">Recent Note</div>
              <div className="italic text-text-secondary">"{client.recent_crm_note}"</div>
            </div>
          </div>
        </Card>
      </div>

      {/* Main Editor */}
      <div className="col-span-9">
        <Card className="min-h-[600px] flex flex-col">
          <div className="px-8 py-6 border-b border-border flex justify-between items-center bg-white">
            <div>
              <div className="text-sm font-label text-text-secondary opacity-70 mb-1">Drafting for</div>
              <h2 className="font-display text-2xl font-bold">{client.name}</h2>
            </div>
            <Button onClick={onComplianceCheck} icon={lucide.ShieldCheck}>
              Run Compliance Check
            </Button>
          </div>

          <div className="p-8 flex-1 bg-white relative">
            {!draftContent ? (
              <div className="space-y-4 animate-pulse">
                <div className="h-4 bg-surface rounded w-3/4"></div>
                <div className="h-4 bg-surface rounded w-full"></div>
                <div className="h-4 bg-surface rounded w-5/6"></div>
              </div>
            ) : (
              <div className="space-y-6">
                {paragraphs.map((p, idx) => {
                  const isSelected = selectedIdx === idx;
                  const hasDiff = isSelected && diffResult;

                  return (
                    <div key={idx} className="relative group">
                      {/* Paragraph Content */}
                      <div 
                        onClick={() => !hasDiff && setSelectedIdx(idx)}
                        className={`p-2 -mx-2 rounded-[2px] transition-colors ${
                          isSelected && !hasDiff ? 'bg-[rgba(0,0,0,0.05)] ring-1 ring-border' : 
                          !hasDiff ? 'hover:bg-surface cursor-text' : ''
                        }`}
                      >
                        {hasDiff ? (
                          <div className="space-y-4">
                            <div className="text-text-secondary line-through opacity-60">
                              <RichTextWithFacts text={diffResult.oldText} />
                            </div>
                            <div className="bg-[rgba(15,138,75,0.1)] p-4 rounded-[2px] border border-[rgba(15,138,75,0.2)] text-text-primary">
                              <RichTextWithFacts text={diffResult.newText} />
                            </div>
                          </div>
                        ) : (
                          <RichTextWithFacts text={p} />
                        )}
                      </div>

                      {/* Floating AI Menu */}
                      <AnimatePresence>
                        {isSelected && (
                          <motion.div 
                            initial={{ opacity: 0, y: 10, scale: 0.95 }}
                            animate={{ opacity: 1, y: 0, scale: 1 }}
                            exit={{ opacity: 0, y: 10, scale: 0.95 }}
                            className="absolute top-full left-0 mt-2 w-[400px] bg-white border border-border shadow-lg rounded-[4px] z-20 overflow-hidden"
                          >
                            {hasDiff ? (
                              <div className="p-4 bg-surface flex justify-end space-x-4">
                                <Button variant="ghost" onClick={rejectDiff} className="h-8 text-sm">Reject</Button>
                                <Button variant="primary" onClick={acceptDiff} className="h-8 text-sm bg-success hover:bg-success/90">Accept Changes</Button>
                              </div>
                            ) : (
                              <div className="p-4">
                                <div className="flex items-center mb-2 text-xs font-label text-nu-red">
                                  <lucide.Sparkles size={14} className="mr-2" /> AI Inline Edit
                                </div>
                                <div className="flex space-x-2">
                                  <input 
                                    type="text" 
                                    value={inlinePrompt}
                                    onChange={(e) => setInlinePrompt(e.target.value)}
                                    placeholder="e.g., Make this sound less alarming..."
                                    className="flex-1 border border-border rounded-[2px] px-4 py-2 text-sm font-body focus:outline-none focus:border-nu-red"
                                    onKeyDown={(e) => e.key === 'Enter' && handleInlineEditSubmit()}
                                  />
                                  <Button 
                                    onClick={handleInlineEditSubmit} 
                                    disabled={isEditing || !inlinePrompt}
                                    className="h-[48px] px-4"
                                  >
                                    {isEditing ? <lucide.Loader2 size={16} className="animate-spin" /> : <lucide.Send size={16} />}
                                  </Button>
                                </div>
                              </div>
                            )}
                          </motion.div>
                        )}
                      </AnimatePresence>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </Card>
      </div>
    </motion.div>
  );
};

const ComplianceReviewScreen = ({ client, onSend }) => {
  const [status, setStatus] = React.useState('scanning'); // scanning, success

  React.useEffect(() => {
    const timer = setTimeout(() => setStatus('success'), 2000);
    return () => clearTimeout(timer);
  }, []);

  const checks = [
    "No promissory language detected",
    "No unapproved securities mentioned",
    "Tone aligns with firm guidelines",
    "Client risk profile matches recommendations"
  ];

  return (
    <motion.div 
      initial={{ opacity: 0, scale: 0.98 }} 
      animate={{ opacity: 1, scale: 1 }} 
      className="max-w-2xl mx-auto mt-16"
    >
      <Card className="overflow-hidden">
        <div className="bg-surface px-8 py-6 border-b border-border text-center">
          <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-white border border-border mb-4 shadow-sm">
            {status === 'scanning' ? (
              <lucide.Scan className="text-nu-red animate-pulse" size={32} />
            ) : (
              <motion.div initial={{ scale: 0 }} animate={{ scale: 1 }} transition={{ type: "spring" }}>
                <lucide.ShieldCheck className="text-success" size={32} />
              </motion.div>
            )}
          </div>
          <h2 className="font-display text-2xl font-bold">
            {status === 'scanning' ? 'Running Compliance Check...' : 'Compliance Check Passed'}
          </h2>
          <p className="font-body text-text-secondary mt-2">
            Verifying communication against SEC/FINRA rules.
          </p>
        </div>

        <div className="p-8">
          <div className="space-y-4 mb-8">
            {checks.map((check, i) => (
              <div key={i} className="flex items-center font-body text-sm">
                {status === 'scanning' ? (
                  <lucide.Loader2 size={18} className="text-text-secondary opacity-50 animate-spin mr-4" />
                ) : (
                  <motion.div 
                    initial={{ opacity: 0, x: -10 }} 
                    animate={{ opacity: 1, x: 0 }} 
                    transition={{ delay: i * 0.1 }}
                  >
                    <lucide.CheckCircle2 size={18} className="text-success mr-4" />
                  </motion.div>
                )}
                <span className={status === 'scanning' ? 'text-text-secondary opacity-50' : 'text-text-primary'}>
                  {check}
                </span>
              </div>
            ))}
          </div>

          <div className="flex justify-end space-x-4 pt-6 border-t border-border">
            <Button variant="secondary" disabled={status === 'scanning'}>Cancel</Button>
            <Button 
              variant="primary" 
              disabled={status === 'scanning'} 
              onClick={onSend}
              icon={lucide.Send}
            >
              Approve & Send to {client.name.split(' ')[0]}
            </Button>
          </div>
        </div>
      </Card>
    </motion.div>
  );
};

// --- Main App ---

const App = () => {
  const [screen, setScreen] = React.useState('dashboard');
  const [selectedEvent, setSelectedEvent] = React.useState(null);
  const [rankedClients, setRankedClients] = React.useState([]);
  const [selectedClient, setSelectedClient] = React.useState(null);
  const [draftContent, setDraftContent] = React.useState("");
  const [toast, setToast] = React.useState(null);

  // Inject NU Brand Styles
  React.useEffect(() => {
    const style = document.createElement('style');
    style.textContent = `
      @import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Mono&family=Open+Sans:ital,wght@0,400;0,600;1,400&family=Roboto+Condensed:wght@400;700&display=swap');

      :root {
        --bg-foundation: #FFFFFF;
        --bg-surface: #F7F7F7;
        --text-primary: #000000;
        --text-secondary: #414141;
        --border: #D9D9D9;

        --nu-red: #C8102E;
        --cream: #F8E5C2;

        --success: #0F8A4B;
        --warning: #B5651D;
        --friction: #9E0A24;
      }

      body {
        background-color: var(--bg-surface);
        color: var(--text-primary);
        font-family: 'Open Sans', sans-serif;
        margin: 0;
        -webkit-font-smoothing: antialiased;
      }

      .font-display { font-family: 'Roboto Condensed', sans-serif; letter-spacing: -0.01em; }
      .font-body { font-family: 'Open Sans', sans-serif; }
      .font-label { font-family: 'Open Sans', sans-serif; font-weight: 600; }
      .font-data { font-family: 'IBM Plex Mono', monospace; }

      .ease-standard { transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1); }
    `;
    document.head.appendChild(style);
    return () => document.head.removeChild(style);
  }, []);

  // State Transitions
  const handleAnalyzeImpact = async (event) => {
    setSelectedEvent(event);
    const ranked = await fetchPrioritizedClients(event, SEED_CLIENTS);
    setRankedClients(ranked);
    setScreen('client_triage');
  };

  const handleDraftOutreach = async (client) => {
    setSelectedClient(client);
    setScreen('email_editor');
    const draft = await fetchDraft(client, selectedEvent);
    setDraftContent(draft);
  };

  const handleComplianceCheck = () => {
    setScreen('compliance_review');
  };

  const handleSend = () => {
    setToast(`Email successfully sent to ${selectedClient.name}`);
    setTimeout(() => setToast(null), 4000);
    setScreen('dashboard');
    // Reset state
    setSelectedEvent(null);
    setRankedClients([]);
    setSelectedClient(null);
    setDraftContent("");
  };

  return (
    <div className="min-h-screen flex flex-col">
      {/* Header */}
      <header className="bg-white border-b border-border h-16 flex items-center px-8 justify-between shrink-0 relative z-50">
        <div className="flex items-center">
          <div className="w-8 h-8 bg-nu-red mr-4 flex items-center justify-center text-white font-display font-bold text-xl leading-none pt-1">N</div>
          <span className="font-display font-bold text-xl tracking-tight">Northeastern University</span>
          <span className="mx-4 text-border">|</span>
          <span className="font-label text-text-secondary">Advisor Copilot</span>
        </div>
        <div className="flex items-center space-x-4 text-sm font-label">
          <span className="text-text-secondary">Elena (Senior Advisor)</span>
          <div className="w-8 h-8 rounded-full bg-surface border border-border flex items-center justify-center">
            <lucide.User size={16} className="text-text-secondary" />
          </div>
        </div>
      </header>

      {/* Demo Controls (Top Right) */}
      <div className="fixed top-24 right-8 z-50 bg-white border border-border p-2 rounded-[4px] shadow-lg flex space-x-2 text-xs font-data">
        <span className="py-1 px-2 text-text-secondary opacity-70">Demo Jump:</span>
        {['dashboard', 'client_triage', 'email_editor', 'compliance_review'].map(s => (
          <button 
            key={s}
            onClick={() => setScreen(s)}
            className={`px-2 py-1 rounded-[2px] ${screen === s ? 'bg-nu-red text-white' : 'hover:bg-surface'}`}
          >
            {s.split('_')[0]}
          </button>
        ))}
      </div>

      {/* Toast */}
      <AnimatePresence>
        {toast && (
          <motion.div 
            initial={{ opacity: 0, y: 50 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: 50 }}
            className="fixed bottom-8 right-8 bg-text-primary text-white px-6 py-4 rounded-[4px] shadow-xl font-body text-sm flex items-center z-50"
          >
            <lucide.CheckCircle2 size={18} className="text-success mr-4" />
            {toast}
          </motion.div>
        )}
      </AnimatePresence>

      {/* Main Content Area */}
      <main className="flex-1 overflow-y-auto pb-24">
        <AnimatePresence mode="wait">
          {screen === 'dashboard' && (
            <DashboardScreen key="dashboard" onAnalyze={handleAnalyzeImpact} />
          )}
          {screen === 'client_triage' && (
            <ClientTriageScreen 
              key="triage" 
              event={selectedEvent || SEED_MARKET_EVENTS[0]} 
              rankedClients={rankedClients}
              onDraft={handleDraftOutreach}
            />
          )}
          {screen === 'email_editor' && (
            <EmailEditorScreen 
              key="editor"
              client={selectedClient || SEED_CLIENTS[0]}
              draftContent={draftContent}
              onComplianceCheck={handleComplianceCheck}
            />
          )}
          {screen === 'compliance_review' && (
            <ComplianceReviewScreen 
              key="compliance"
              client={selectedClient || SEED_CLIENTS[0]}
              onSend={handleSend}
            />
          )}
        </AnimatePresence>
      </main>
    </div>
  );
};

function __test_state_transitions__() {
  console.assert(typeof App === 'function', 'App must be a component');
  return true;
}
if (typeof window !== 'undefined') {
  window.__hicProtoTests = __test_state_transitions__;
}
